import{c as t,Q as o,j as a,m as r}from"./chunks/framework.BXc4yaFE.js";const p=JSON.parse('{"title":"CLAUDE.md","description":"","frontmatter":{},"headers":[],"relativePath":"research/reports/2026-06-06-autoload-en/CLAUDE.md","filePath":"research/reports/2026-06-06-autoload-en/CLAUDE.md","lastUpdated":1780842316000}'),i={name:"research/reports/2026-06-06-autoload-en/CLAUDE.md"};function s(d,e,n,l,c,u){return o(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="claude-md" tabindex="-1">CLAUDE.md <a class="header-anchor" href="#claude-md" aria-label="Permalink to &quot;CLAUDE.md&quot;">​</a></h1><blockquote><p>Traditional Chinese preferred · English supported · Tasks unrelated to this workspace → <code>/clear</code>. Sub-agents do not inherit this file; parent instructs sub-agent &quot;Read AGENTS.md first&quot;. This file ≤ 200 lines (Mnilax: compliance drops sharply beyond this). Auto-load five-source byte threshold (three-tier soft limit, canonical unit: byte) — see core.md §Framework Integrity.</p></blockquote><h2 id="the-loop-behavioral-contract-—-six-phase-meta-loop" tabindex="-1">The Loop (Behavioral Contract — Six-Phase Meta-Loop) <a class="header-anchor" href="#the-loop-behavioral-contract-—-six-phase-meta-loop" aria-label="Permalink to &quot;The Loop (Behavioral Contract — Six-Phase Meta-Loop)&quot;">​</a></h2><blockquote><p>Each phase answers &quot;which failure mode does this prevent?&quot;. Reference basis: Karpathy R1–R4 + Mnilax R5–R12 (original 12 rules reorganized into six phases). Mandatory clauses = <code>core.md</code>; checklist + paper grounding = <code>refs/karpathy-mnilax-best-solution.md</code>. Improvement/audit tasks follow these six phases, each mechanically verifiable (bash/test); gate before destructive APPLY.</p></blockquote><table tabindex="0"><thead><tr><th>Phase</th><th>Discipline</th><th>Prevents</th></tr></thead><tbody><tr><td><strong>OBSERVE</strong></td><td>Read before acting + on-rails/off-rails classification</td><td>Editing without reading</td></tr><tr><td><strong>IDENTIFY</strong></td><td>Surface assumptions + verifiable success criteria (incl. four-dimension quality)</td><td>Silent assumptions / weak criteria</td></tr><tr><td><strong>PROPOSE</strong></td><td>Minimal + surgical (AI four-defect self-check)</td><td>Over-engineering / peripheral pollution</td></tr><tr><td><strong>APPLY</strong></td><td>Convention-first + destructive gate (derivable = noise)</td><td>silent fork</td></tr><tr><td><strong>TEST</strong></td><td>Tests verify intent + Fail Loud/PGE/unverified_success</td><td>Fake tests / silent failure</td></tr><tr><td><strong>RECORD</strong></td><td>Checkpoint + reflection into store (self-evolution)</td><td>Running on broken state</td></tr><tr><td><strong>Cross-cutting</strong></td><td>Judgment vs. decision / surface contradictions / Token budget</td><td>LLM making deterministic decisions / mixing contradictions / loop runaway</td></tr></tbody></table><h2 id="always-loaded-rules-auto-load" tabindex="-1">Always-loaded Rules (Auto-load) <a class="header-anchor" href="#always-loaded-rules-auto-load" aria-label="Permalink to &quot;Always-loaded Rules (Auto-load)&quot;">​</a></h2><ul><li>@.claude/rules/core.md — The Loop six-phase mandatory clauses · cross-cutting discipline · Git workflow · production red lines</li><li>@.claude/rules/context-management.md — Token budget · Compact · Prompt Caching</li><li>@.claude/rules/output-discipline.md — No preamble · filler words banned · concise output (cross-cuts all phases)</li><li>@.claude/rules/subagent-strategy.md — Delegation decision · Fan-out · Advisor mode</li></ul><blockquote><p><code>.claude/rules/security-hygiene.md</code> is path-scoped on-demand (triggered when editing .env / credentials files).</p></blockquote><h2 id="modes-effort" tabindex="-1">Modes &amp; Effort <a class="header-anchor" href="#modes-effort" aria-label="Permalink to &quot;Modes &amp; Effort&quot;">​</a></h2><blockquote><p><strong>Modes</strong>: Default Sonnet 4.6; <code>/haiku-pilot</code> (cost) <code>/sonnet-pilot</code> (quality) <code>/opus-pilot</code> (architecture/security). <strong>Effort (Opus 4.8)</strong>: <code>/effort low</code>(quick)·<code>high</code>(daily)·<code>xhigh</code>(agentic/review)·<code>max</code>(hardest)·<code>/fast</code>(refactor)·<code>ultracode</code>(=xhigh+dynamic workflow). Matrix+pricing in <code>refs/pilot-shared-preflights.md</code> §E.</p></blockquote>',10)])])}const f=t(i,[["render",s]]);export{p as __pageData,f as default};
